// Serati Lens — fungsi server (Vercel) untuk mengenali foto upakara dengan AI.
// Kunci API disimpan sebagai Environment Variable di Vercel, BUKAN di kode ini. Boleh diisi lebih dari satu;
// semua penyedia yang kuncinya terpasang akan dicoba bergantian sampai ada yang menjawab.
//   GEMINI_API_KEY    → Google Gemini (kuota gratis lewat Google AI Studio). Opsional: GEMINI_MODEL (dicoba paling awal).
//   GROQ_API_KEY      → Groq (kuota gratis lewat console.groq.com). Opsional: GROQ_MODELS (dipisah koma).
//   GITHUB_MODELS_TOKEN → GitHub Models (gratis, token GitHub dengan izin Models: Read-only). Opsional: GITHUB_MODELS (dipisah koma).
//   ANTHROPIC_API_KEY → Claude API (berbayar). Opsional: LENS_MODEL.
// Cek kesehatan di browser: /api/lens?cek=1 (gambar kecil) atau /api/lens?cek=2 (foto 800x600).

const CATALOG = "- canang-sari | Canang Sari | Canang | ciri: Ceper kecil persegi atau bulat dengan sampian bintang/bundar di atasnya; bunga empat warna tersusun per sisi; kembang rampe hijau di tengah; ada irisan tebu, pisang, atau jajan di bawah sampian.\n- canang-genten | Canang Genten | Canang | ciri: Kecil dan sederhana; hanya satu wadah bunga kerucut atau bundar; tidak ada irisan tebu, pisang, atau jajan.\n- canang-burat-wangi | Canang Burat Wangi (Canang Lenga Wangi–Burat Wangi) | Canang | ciri: Ada tiga wadah kecil: pasta kuning (burat wangi), minyak gelap, dan minyak bening; bagian atas seperti canang genten.\n- canang-pasucian | Canang Pasucian (Canang Pabersihan) | Canang | ciri: Banyak wadah kecil (tujuh celemik) berisi bubuk berwarna: hitam (sisig), hijau (ambuh), kuning (kekosok), putih (tepung tawar).\n- canang-gantal | Canang Gantal | Canang | ciri: Ada ikatan gulungan sirih (tujuh gulungan) yang terlihat jelas di bawah sampian.\n- canang-pangraos | Canang Pangraos | Canang | ciri: Dua tingkat; terlihat kojong-kojong kecil, lembaran sirih, tembakau, dan rokok; canang sari di puncak.\n- canang-tubungan | Canang Tubungan | Canang | ciri: Dua gulungan sirih bersilang (bentuk X) di bawah sampian.\n- canang-tadah-sukla | Canang Tadah Sukla (Tadah Pawitra) | Canang | ciri: Mirip canang genten, tetapi ada satu wadah kecil berisi potongan umbi dan kacang goreng berwarna cokelat.\n- canang-raka | Canang Raka (Canang Meraka) | Canang | ciri: Lebih besar dari canang sari; isi buah dan jajan terlihat jelas; sampian di atasnya.\n- canang-rebong | Canang Rebong | Canang | ciri: Tinggi dan menjulang, didominasi bunga warna-warni yang ditancapkan rapat pada batang di atas dulang.\n- gebogan-woh-wohan | Gebogan Woh-wohan | Gebogan | ciri: Menara kerucut di atas dulang kayu, didominasi buah utuh (jeruk, salak, apel, pisang, dan lainnya), sampian janur di puncak.\n- gebogan-jaja | Gebogan Jaja | Gebogan | ciri: Menara kerucut yang didominasi jajan berwarna (putih, merah muda, cokelat), bukan buah.\n- gebogan-bunga | Gebogan Bunga | Gebogan | ciri: Menara kerucut yang hampir seluruhnya bunga (oranye gumitir, putih jepun), tanpa buah besar.\n- gebogan-agung | Gebogan Agung | Gebogan | ciri: Jauh lebih tinggi dari gebogan biasa; campuran buah, jajan, dan bunga; sampian besar di puncak.\n- sampian-canang-sari | Sampian Canang Sari (Sampian Uras Sari) | Sampian | ciri: Anyaman janur kuning-hijau muda berbentuk bintang atau bunga bundar, kosong tanpa makanan.\n- sampian-sodan | Sampian Sodan (Sampian Plaus / Kepet-kepetan) | Sampian | ciri: Anyaman janur melebar seperti kipas, biasanya di atas banten berisi nasi atau penek dan lauk.\n- sampian-pejati | Sampian Pejati (Sampian Peras) | Sampian | ciri: Sampian janur yang lebih besar dan bertingkat, berada di puncak banten peras dalam satu set pejati.\n- sampian-gantung | Sampian Gantung | Sampian | ciri: Anyaman janur menjuntai ke bawah dan tergantung, sering bersama lamak (panel janur panjang).\n- tamiang | Tamiang | Sampian | ciri: Bundar seperti perisai atau roda dengan pola janur memancar dari tengah.\n- segehan-kepel-putih | Segehan Kepel Putih | Segehan | ciri: Alas daun kecil berisi dua bulatan nasi putih, irisan bawang dan jahe, sedikit garam.\n- segehan-putih-kuning | Segehan Putih Kuning | Segehan | ciri: Dua bulatan nasi berbeda warna, putih dan kuning, berdampingan.\n- segehan-manca-warna | Segehan Manca Warna | Segehan | ciri: Empat atau lima bulatan nasi berbeda warna (putih, merah, kuning, hitam) tersusun melingkar di atas daun.\n- segehan-cacahan | Segehan Cacahan (Segehan Cah-cahan) | Segehan | ciri: Nasi terlihat berbutir dan tersebar, bukan bulatan padat.\n- segehan-agung | Segehan Agung | Segehan | ciri: Lebih besar dan terdiri dari banyak tanding segehan sekaligus.";
const IDS = new Set(["canang-sari","canang-genten","canang-burat-wangi","canang-pasucian","canang-gantal","canang-pangraos","canang-tubungan","canang-tadah-sukla","canang-raka","canang-rebong","gebogan-woh-wohan","gebogan-jaja","gebogan-bunga","gebogan-agung","sampian-canang-sari","sampian-sodan","sampian-pejati","sampian-gantung","tamiang","segehan-kepel-putih","segehan-putih-kuning","segehan-manca-warna","segehan-cacahan","segehan-agung"]);
const ALLOWED_TYPES = new Set(["image/jpeg", "image/png", "image/webp"]);
const MAX_B64 = 4000000;          // ~3 MB gambar asli; foto dari aplikasi sudah dikompres
const RATE_LIMIT = 20;            // permintaan per menit per alamat IP (perlindungan sederhana)
const PER_TRY_MS = Number(process.env.LENS_TRY_MS) || 7000;    // batas tunggu per model (putaran pertama)
const TOTAL_MS = Number(process.env.LENS_TOTAL_MS) || 31000;   // batas tunggu keseluruhan (aplikasi menunggu maks. 35 detik)
const hits = new Map();

const PROMPT = "Kamu adalah fitur pengenal foto di aplikasi Serati, katalog upakara (sesajen) Hindu Bali. " +
  "Pengguna memotret satu benda. Cocokkan foto dengan SATU item dari katalog berikut berdasarkan ciri visualnya.\n\n" +
  "KATALOG (id | nama | kategori | ciri):\n" + CATALOG + "\n\n" +
  "Aturan:\n- Pilih id dari katalog saja. Jika foto bukan upakara Bali atau tidak cocok dengan item mana pun, isi \"id\": null.\n" +
  "- \"keyakinan\" antara 0 dan 1; jujur jika ragu (beberapa jenis canang tampak mirip).\n" +
  "- \"alasan\": 1-2 kalimat bahasa Indonesia tentang ciri yang terlihat di foto.\n" +
  "- \"alternatif\": maksimal 2 id lain yang mungkin, beserta keyakinannya.\n\n" +
  "Balas HANYA JSON: {\"id\": string|null, \"keyakinan\": number, \"alasan\": string, \"alternatif\": [{\"id\": string, \"keyakinan\": number}]}";

function clamp01(x) { const n = Number(x); return Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0; }
function cleanKey(v) { return String(v || "").trim().replace(/^["']|["']$/g, ""); }

function rateLimited(ip) {
  const now = Date.now();
  const arr = (hits.get(ip) || []).filter(t => now - t < 60000);
  arr.push(now); hits.set(ip, arr);
  if (hits.size > 5000) hits.clear();
  return arr.length > RATE_LIMIT;
}

function parseModelJson(text) {
  const t = String(text || "").replace(/<think>[\s\S]*?<\/think>/gi, "");
  const m = t.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch (e) { return null; }
}

// Kapan pindah ke model berikutnya (bukan berhenti)
function shouldTryNext(status, message) {
  if (status === 404 || status === 429 || status >= 500) return true;          // tidak ada / kuota model habis / sibuk
  if ((status === 400 || status === 422) && /model|not found|not supported|unsupported|thinking|reasoning|response_format|json|image/i.test(message)) return true;
  if (status === 401 || status === 403) return true;                            // kunci penyedia ini bermasalah → coba penyedia lain
  return false;
}

async function timedFetch(url, options, wait) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), wait);
  try { return await fetch(url, Object.assign({}, options, { signal: ctrl.signal })); }
  finally { clearTimeout(timer); }
}

async function readError(r) {
  try { const e = await r.json(); const err = e && e.error; return String((err && (err.message || err.status)) || (typeof err === "string" ? err : "") || "").slice(0, 300); }
  catch (e) { return ""; }
}

/* ---------- Penyedia: Google Gemini ---------- */
async function callGemini(key, model, image, mediaType, wait, useThinking) {
  const generationConfig = { responseMimeType: "application/json" };
  if (useThinking) generationConfig.thinkingConfig = { thinkingLevel: "low" };
  const r = await timedFetch("https://generativelanguage.googleapis.com/v1beta/models/" + encodeURIComponent(model) + ":generateContent", {
    method: "POST",
    headers: { "x-goog-api-key": key, "content-type": "application/json" },
    body: JSON.stringify({ contents: [{ role: "user", parts: [{ inlineData: { mimeType: mediaType, data: image } }, { text: PROMPT }] }], generationConfig })
  }, wait);
  if (!r.ok) return { status: r.status, message: await readError(r) };
  const data = await r.json();
  const parts = (((data.candidates || [])[0] || {}).content || {}).parts || [];
  return { status: 200, text: parts.filter(p => p && typeof p.text === "string" && !p.thought).map(p => p.text).join("") };
}
async function geminiTry(key, model, image, mediaType, wait) {
  const t0 = Date.now();
  let r = await callGemini(key, model, image, mediaType, wait, true);
  if (r.status === 400 && /thinking/i.test(r.message || "")) r = await callGemini(key, model, image, mediaType, Math.max(1000, wait - (Date.now() - t0)), false);
  return r;
}

/* ---------- Penyedia berformat OpenAI: Groq & GitHub Models ---------- */
const OAI = {
  groq:   { url: "https://api.groq.com/openai/v1/chat/completions", maxKey: "max_completion_tokens", headers: {} },
  github: { url: "https://models.github.ai/inference/chat/completions", maxKey: "max_tokens", headers: { "accept": "application/vnd.github+json", "x-github-api-version": "2022-11-28" } }
};
async function callOAI(p, key, model, image, mediaType, wait, jsonMode) {
  const cfg = OAI[p];
  const body = {
    model,
    messages: [{ role: "user", content: [{ type: "text", text: PROMPT }, { type: "image_url", image_url: { url: "data:" + mediaType + ";base64," + image } }] }],
    temperature: 0.2
  };
  body[cfg.maxKey] = 600;
  if (jsonMode) body.response_format = { type: "json_object" };
  const r = await timedFetch(cfg.url, {
    method: "POST",
    headers: Object.assign({ "authorization": "Bearer " + key, "content-type": "application/json" }, cfg.headers),
    body: JSON.stringify(body)
  }, wait);
  if (!r.ok) return { status: r.status, message: await readError(r) };
  const data = await r.json();
  const msg = (((data.choices || [])[0] || {}).message || {});
  return { status: 200, text: typeof msg.content === "string" ? msg.content : "" };
}
async function oaiTry(p, key, model, image, mediaType, wait) {
  const t0 = Date.now();
  let r = await callOAI(p, key, model, image, mediaType, wait, true);
  if ((r.status === 400 || r.status === 422) && /response_format|json/i.test(r.message || "")) r = await callOAI(p, key, model, image, mediaType, Math.max(1000, wait - (Date.now() - t0)), false);
  return r;
}

/* ---------- Penyedia: Claude ---------- */
async function claudeTry(key, model, image, mediaType, wait) {
  const r = await timedFetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model, max_tokens: 400, messages: [{ role: "user", content: [
      { type: "image", source: { type: "base64", media_type: mediaType, data: image } }, { type: "text", text: PROMPT }] }] })
  }, wait);
  if (!r.ok) return { status: r.status, message: await readError(r) };
  const data = await r.json();
  return { status: 200, text: (Array.isArray(data.content) ? data.content : []).filter(b => b && b.type === "text").map(b => b.text).join("") };
}

/* ---------- Daftar model yang dicoba (urutan: kualitas & kecepatan, diselang-seling antarpenyedia) ---------- */
function uniq(a) { return a.filter((m, i) => m && a.indexOf(m) === i); }
function candidates() {
  const gk = cleanKey(process.env.GEMINI_API_KEY), qk = cleanKey(process.env.GROQ_API_KEY), hk = cleanKey(process.env.GITHUB_MODELS_TOKEN), ck = cleanKey(process.env.ANTHROPIC_API_KEY);
  const list = v => String(v || "").split(",").map(x => x.trim());
  const gem = gk ? uniq([process.env.GEMINI_MODEL, "gemini-3.8-flash", "gemini-3.7-flash", "gemini-flash-latest", "gemini-flash-lite-latest", "gemini-3.5-flash-lite"])
    .map(m => ({ provider: "gemini", model: m, run: (img, mt, w) => geminiTry(gk, m, img, mt, w) })) : [];
  const ghb = hk ? uniq([...list(process.env.GITHUB_MODELS), "openai/gpt-4.1-mini", "openai/gpt-4o-mini", "openai/gpt-4.1", "openai/gpt-4o"])
    .map(m => ({ provider: "github", model: m, run: (img, mt, w) => oaiTry("github", hk, m, img, mt, w) })) : [];
  const grq = qk ? uniq([...list(process.env.GROQ_MODELS), "qwen/qwen3.8-27b", "qwen/qwen3.6-27b", "meta-llama/llama-4-scout-17b-16e-instruct"])
    .map(m => ({ provider: "groq", model: m, run: (img, mt, w) => oaiTry("groq", qk, m, img, mt, w) })) : [];
  const cla = ck ? [process.env.LENS_MODEL || "claude-haiku-5-5"].map(m => ({ provider: "claude", model: m, run: (img, mt, w) => claudeTry(ck, m, img, mt, w) })) : [];
  const out = [];
  const max = Math.max(gem.length, ghb.length, grq.length);
  for (let i = 0; i < max; i++) {               // selang-seling: Gemini, GitHub, Groq, Gemini, GitHub, Groq, ...
    if (gem[i]) out.push(gem[i]);
    if (ghb[i]) out.push(ghb[i]);
    if (grq[i]) out.push(grq[i]);
  }
  return out.concat(cla);
}

async function askAll(image, mediaType, attempts = []) {
  const deadline = Date.now() + TOTAL_MS;
  let queue = candidates();
  if (!queue.length) return { status: 503, attempts, notConfigured: true };
  const dead = new Set();                         // penyedia yang kuncinya ditolak → lewati model-model lainnya
  for (let round = 1; round <= 2 && queue.length; round++) {
    const busy = [];
    for (const c of queue) {
      if (dead.has(c.provider)) continue;
      const left = deadline - Date.now();
      if (left < 2500) break;
      const wait = round === 1 ? Math.min(PER_TRY_MS, left) : left - 500;
      let r;
      try { r = await c.run(image, mediaType, wait); }
      catch (e) {
        const timeout = e && e.name === "AbortError";
        r = { status: timeout ? 504 : 502, message: timeout ? "tidak menjawab dalam " + Math.round(wait / 1000) + " detik" : String((e && e.message) || e).slice(0, 200) };
      }
      attempts.push(Object.assign({ penyedia: c.provider, model: c.model, putaran: round }, r.status === 200 ? { status: 200 } : { status: r.status, message: r.message }));
      if (r.status === 200) {
        const out = parseModelJson(r.text);
        if (out && typeof out === "object") return { status: 200, attempts, out, provider: c.provider, model: c.model };
        attempts[attempts.length - 1].message = "jawaban bukan JSON";
        continue;                                // jawaban rusak → coba model lain
      }
      if (r.status === 503 || r.status === 504 || r.status === 429) busy.push(c);
      if (!shouldTryNext(r.status, r.message || "")) dead.add(c.provider);
    }
    queue = busy;                                // putaran kedua: ulangi yang tadi sibuk
    if (queue.length && deadline - Date.now() > 4000) await new Promise(res => setTimeout(res, 1500));
  }
  const last = attempts[attempts.length - 1] || { status: 504 };
  return { status: last.status === 200 ? 502 : last.status, attempts, invalid: last.status === 200 };
}

function sanitize(out) {
  const id = typeof out.id === "string" && IDS.has(out.id) ? out.id : null;
  const alternatif = (Array.isArray(out.alternatif) ? out.alternatif : [])
    .filter(a => a && IDS.has(a.id) && a.id !== id).slice(0, 2)
    .map(a => ({ id: a.id, keyakinan: clamp01(a.keyakinan) }));
  return { id, keyakinan: clamp01(out.keyakinan), alasan: String(out.alasan || "").slice(0, 400), alternatif };
}

/* ---------- Cek kesehatan ---------- */
const TEST_PNG = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGP4z8AAAAMBAQDJ/pLvAAAAAElFTkSuQmCC";
const TEST_JPG = "";
async function diagnose(req, res) {
  const g = String(process.env.GEMINI_API_KEY || ""), q = String(process.env.GROQ_API_KEY || "");
  const info = {
    penyedia_terpasang: { gemini: !!cleanKey(g), github: !!cleanKey(process.env.GITHUB_MODELS_TOKEN), groq: !!cleanKey(q), claude: !!cleanKey(process.env.ANTHROPIC_API_KEY) },
    kunci_gemini: { terpasang: !!cleanKey(g), panjang: cleanKey(g).length, ada_spasi_atau_kutip_tersalin: g !== cleanKey(g) },
    kunci_groq: { terpasang: !!cleanKey(q), diawali_gsk: cleanKey(q).startsWith("gsk_"), ada_spasi_atau_kutip_tersalin: q !== cleanKey(q) },
    token_github: { terpasang: !!cleanKey(process.env.GITHUB_MODELS_TOKEN), diawali_github_pat: cleanKey(process.env.GITHUB_MODELS_TOKEN).startsWith("github_pat_") }
  };
  const ip = String(req.headers["x-forwarded-for"] || "").split(",")[0].trim() || "anon";
  if (rateLimited(ip)) { res.status(429).json({ error: "rate_limited" }); return; }
  const photo = /[?&]cek=2\b/.test(String(req.url || ""));
  info.uji = photo ? "foto 800x600" : "gambar 1x1";
  const attempts = []; const t0 = Date.now();
  try {
    const r = await askAll(photo ? TEST_JPG : TEST_PNG, photo ? "image/jpeg" : "image/png", attempts);
    info.berhasil = r.status === 200;
    if (info.berhasil) info.model_dipakai = r.provider + " / " + r.model;
    if (r.notConfigured) info.galat = "belum ada kunci API yang terpasang";
  } catch (e) { info.berhasil = false; info.galat = String((e && e.message) || e); }
  info.percobaan = attempts; info.waktu_ms = Date.now() - t0;
  res.status(200).json(info);
}

/* ---------- Pintu masuk ---------- */
module.exports = async function handler(req, res) {
  res.setHeader("Cache-Control", "no-store");
  if (req.method === "GET" && /[?&]cek=[12]\b/.test(String(req.url || ""))) { await diagnose(req, res); return; }
  if (req.method !== "POST") { res.status(405).json({ error: "method_not_allowed" }); return; }

  const ip = String(req.headers["x-forwarded-for"] || "").split(",")[0].trim() || "anon";
  if (rateLimited(ip)) { res.status(429).json({ error: "rate_limited" }); return; }

  let body = req.body;
  if (typeof body === "string") { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const image = body && body.image;
  const mediaType = body && body.mediaType;
  if (typeof image !== "string" || !image || !ALLOWED_TYPES.has(mediaType) || !/^[A-Za-z0-9+/=]+$/.test(image)) {
    res.status(400).json({ error: "bad_request" }); return;
  }
  if (image.length > MAX_B64) { res.status(413).json({ error: "too_large" }); return; }

  try {
    const r = await askAll(image, mediaType);
    if (r.notConfigured) { res.status(503).json({ error: "lens_not_configured" }); return; }
    if (r.status !== 200) {
      console.error("Serati Lens: semua model gagal", JSON.stringify(r.attempts));
      const allBusy = r.attempts.length && r.attempts.every(a => a.status === 429);
      res.status(allBusy ? 429 : 502).json({ error: r.invalid ? "invalid_json" : (allBusy ? "rate_limited" : "upstream_error") });
      return;
    }
    res.status(200).json(sanitize(r.out));
  } catch (e) {
    console.error("Serati Lens: galat", e && e.name, e && e.message);
    res.status(502).json({ error: "upstream_error" });
  }
};
